<?php require_once __DIR__ . '/partials.php'; require_admin(); require_once __DIR__ . '/../config/database.php'; admin_header('Invoices'); $invoices = []; try { $invoices = db()->query('SELECT * FROM invoices ORDER BY created_at DESC')->fetchAll(); } catch (Throwable $exception) {} ?>
<?php if ($message = flash('success')): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?>
<section class="panel"><table><thead><tr><th>Invoice</th><th>Client</th><th>Service</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($invoices as $invoice): ?><tr><td><?= e($invoice['invoice_number']) ?></td><td><?= e($invoice['client_name']) ?></td><td><?= e($invoice['service_name']) ?></td><td><?= money($invoice['amount']) ?></td><td><span class="badge <?= strtolower(e($invoice['payment_status'])) ?>"><?= e($invoice['payment_status']) ?></span></td><td><a href="../invoice.php?invoice=<?= urlencode($invoice['invoice_number']) ?>">View</a><form class="inline" action="../actions/update-invoice-status.php" method="post"><input type="hidden" name="invoice_id" value="<?= (int) $invoice['id'] ?>"><select name="payment_status"><option <?= $invoice['payment_status'] === 'Pending' ? 'selected' : '' ?>>Pending</option><option <?= $invoice['payment_status'] === 'Paid' ? 'selected' : '' ?>>Paid</option><option <?= $invoice['payment_status'] === 'Cancelled' ? 'selected' : '' ?>>Cancelled</option></select><button>Update</button></form></td></tr><?php endforeach; if (!$invoices): ?><tr><td colspan="6">No invoices found. Confirm database setup if this is unexpected.</td></tr><?php endif; ?></tbody></table></section>
<?php admin_footer(); ?>
